make_models.each do |make_model|
  puts "Creating: make_id=#{make_model[:vehicle_make_id]}, en=#{make_model[:name_en]}, ar=#{make_model[:name_ar]}"

  VehicleModel.create!(
    vehicle_make: VehicleMake.find(make_model[:vehicle_make_id]),
    name_en: make_model[:name_en],
    name_ar: make_model[:name_ar]
  )
end

